const { jql, maxResults, fields, nextPageToken } = $.input;

if (!jql) throw new Error('jql query is required');

const max = Math.max(1, Math.min(100, maxResults || 20));
const fieldList = fields || 'summary,status,assignee,priority,created,updated';

const params = {
  jql: jql,
  maxResults: String(max),
  fields: fieldList
};

if (nextPageToken) params.nextPageToken = nextPageToken;

return { params, jql, max };

const resp = $.steps.searchIssues.response || {};
const issues = (resp.issues || []).map(issue => {
  const f = issue.fields || {};
  return {
    id: issue.id,
    key: issue.key,
    summary: f.summary || '',
    status: f.status ? f.status.name : '',
    statusCategory: f.status && f.status.statusCategory ? f.status.statusCategory.name : '',
    assignee: f.assignee ? f.assignee.displayName : 'Unassigned',
    assigneeAccountId: f.assignee ? f.assignee.accountId : null,
    priority: f.priority ? f.priority.name : '',
    created: f.created || '',
    updated: f.updated || ''
  };
});

const result = {
  issues,
  totalFound: issues.length,
  isLast: resp.isLast !== false,
  jql: $.steps.buildParams.output.jql,
  summary: `Found ${issues.length} issue${issues.length === 1 ? '' : 's'} matching JQL query`
};

if (resp.nextPageToken) result.nextPageToken = resp.nextPageToken;

return result;
